//! Isolated offline acceptance. Never opens an existing user profile.
use crate::{core_api::{self,Action},engine::Engine,model::*,purposes,rpc::Rpc,setup::Settings};
use serde_json::{json,Value};
use std::{fs,path::PathBuf,sync::{Arc,atomic::Ordering},time::{Duration,Instant}};
fn wait(e:&Engine){let end=Instant::now()+Duration::from_secs(20);while e.worker.load(Ordering::SeqCst)&&Instant::now()<end{std::thread::sleep(Duration::from_millis(20));}assert!(!e.worker.load(Ordering::SeqCst),"OFFLINE peer timeout");}
fn fixture(label:&str)->(PathBuf,Arc<Engine>){
 let p=PathBuf::from(std::env::var_os("AI_GUILD_TEST_ROOT").expect("explicit isolated root")).join(format!("purpose-{label}-{}",id()));fs::create_dir_all(p.join("output")).unwrap();fs::write(p.join(".ai-guild-qa"),"OFFLINE only").unwrap();
 let e=Engine::open(&p,None).unwrap();e.save_setup(Settings{work_root:p.to_string_lossy().into(),output_root:p.join("output").to_string_lossy().into(),approval_policy:"on-request".into(),..Default::default()}).unwrap();
 fs::write(p.join("offline-plan.json"),json!({"title":"OFFLINE language fixture","requirements":["小さく始める"],"checklist":["原文を保持"],"files":[{"name":"post.txt","requiredText":["小さく始める"]}]}).to_string()).unwrap();
 fs::write(p.join("offline-event.html"),json!({"files":[{"name":"post.txt","content":"小さく始める。\nOFFLINE fixture only, not evidence of English generation quality.\n"}]}).to_string()).unwrap();
 *e.rpc.lock().unwrap()=Some(Rpc::phase9_fixture(&p).unwrap());(p,e)
}
fn input(lang:&str)->Value{json!({"theme":"  小さく始める\r\n固定文言を維持  ","context":"対象: 提供資料の読者\n媒体: 投稿用文章案\n外部投稿不要。","contentLanguage":lang})}
fn start(e:&Arc<Engine>,lang:&str)->Result<Value,String>{core_api::start_prepared_purpose(e,purposes::prepare(purposes::SOCIAL,purposes::PRIOR_VERSION,input(lang)).unwrap(),Some(crate::integrations::PlanInput{goal:crate::integrations::Goal::ExportPackage,..Default::default()}))}
fn write(p:&std::path::Path,name:&str,v:&Value){fs::write(p.join(name),serde_json::to_vec_pretty(v).unwrap()).unwrap();}
fn counts(e:&Engine)->(i64,i64){let d=e.data.lock().unwrap();(d.store.0.query_row("SELECT count(*) FROM jobs",[],|r|r.get(0)).unwrap(),d.store.0.query_row("SELECT count(*) FROM purpose_job_context",[],|r|r.get(0)).unwrap())}
#[test]fn purpose_new_start_atomic_context_approval_artifacts_and_restart(){
 for lang in ["ja","en"]{let(p,e)=fixture(lang);let result=start(&e,lang).unwrap();wait(&e);let s=e.snapshot();let j=s.job.as_ref().unwrap();let c=&s.purpose_job_context[&j.job_id];assert_eq!(result["jobId"],j.job_id);assert_eq!(j.workflow_id,crate::general::ID);assert!(crate::sns::applies(j));assert_eq!(j.status,"awaiting_approval");assert_eq!(c.content_language,lang);assert_eq!(c.submitted_input,input(lang));purposes::validate_context(c,j).unwrap();assert_eq!(counts(&e),(1,1));assert!(matches!(s.completion_plans[&j.job_id].goal,crate::integrations::Goal::ExportPackage));
  let artifact=j.artifacts.iter().find(|a|a.name=="post.txt").unwrap();let bytes=fs::read(&artifact.path).unwrap();assert_eq!(purposes::sha256(&bytes),artifact.sha256);assert!(start(&e,lang).is_err());let context=c.clone();let approval=&s.approvals[0];
  e.answer_content_review(&j.job_id,&approval.id,"accept").unwrap();wait(&e);let complete=e.snapshot();assert_eq!(complete.job.as_ref().unwrap().status,"completed");crate::sns::approved(complete.job.as_ref().unwrap()).unwrap();let copy=core_api::perform(&e,Action::ReadText{job_id:j.job_id.clone(),path:artifact.path.clone(),purpose:"copy".into()}).unwrap();assert_eq!(copy["sha256"],artifact.sha256);assert_eq!(fs::read(&artifact.path).unwrap(),bytes);
  write(&p,"purpose-result.json",&json!({"result":"OFFLINE_PASS","context":context,"snapshot":core_api::snapshot(&complete),"realInference":0,"englishQuality":"NOT_VERIFIED"}));
  e.get_rpc().unwrap().shutdown();assert_eq!(fs::read_to_string(p.join("offline-peer.jsonl")).unwrap().lines().count(),2);drop(e);let reopened=Engine::open(&p,None).unwrap();assert_eq!(reopened.snapshot().purpose_job_context[&j.job_id],context);assert_eq!(reopened.snapshot().job.as_ref().unwrap().status,"completed");assert_eq!(counts(&reopened),(1,1));
 }
}
#[test]fn purpose_context_insert_failure_rolls_back_job_state_events_and_execution(){
 let(p,e)=fixture("atomic-failure");let before=serde_json::to_value(e.snapshot()).unwrap();e.data.lock().unwrap().store.0.execute_batch("CREATE TRIGGER fail_purpose AFTER INSERT ON purpose_job_context BEGIN SELECT RAISE(ABORT,'injected context failure'); END;").unwrap();
 let error=start(&e,"ja").unwrap_err();assert!(error.starts_with("[PURPOSE_NOT_STARTED] "));assert!(error.contains("injected context failure"));assert!(!e.worker.load(Ordering::SeqCst));assert_eq!(serde_json::to_value(e.snapshot()).unwrap(),before);assert_eq!(counts(&e),(0,0));assert!(!p.join("offline-peer.jsonl").exists());let loaded=e.data.lock().unwrap().store.load().unwrap().unwrap();assert!(loaded.job.is_none());assert!(loaded.events.iter().all(|e|e.event_type!="job_started"));
 write(&p,"failure-result.json",&json!({"result":"OFFLINE_PASS","error":error,"jobs":0,"contexts":0,"rpcTurns":0,"stateRolledBack":true,"orphanWorkspace":"empty directory may remain; no Job success or worker"}));e.get_rpc().unwrap().shutdown();
}
#[test]fn purpose_legacy_sns_and_unclassified_history_are_readonly_projections(){
 let(p,e)=fixture("legacy");let result=core_api::perform(&e,Action::Start{workflow_id:crate::sns::ID.into(),instruction:"小さく始める文章案。外部投稿不要。".into(),completion_plan:None}).unwrap();wait(&e);let s=e.snapshot();let j=s.job.as_ref().unwrap();let id=j.job_id.clone();let old=serde_json::to_value(&s).unwrap();let v=core_api::snapshot(&s);assert_eq!(v["jobs"][0]["purpose"]["purposeId"],"social-text");assert_eq!(v["jobs"][0]["purpose"]["contentLanguage"],Value::Null);assert_eq!(v["jobs"][0]["purpose"]["contextSource"],"LEGACY_SNS_PROJECTION");assert_eq!(j.workflow_id,crate::general::ID);assert!(s.purpose_job_context.is_empty());assert_eq!(serde_json::to_value(&s).unwrap(),old);assert_eq!(result["jobId"],id);
 e.control("stop".into()).unwrap();e.get_rpc().unwrap().shutdown();*e.rpc.lock().unwrap()=Some(Rpc::phase9_fixture(&p).unwrap());let prior=e.snapshot().job.unwrap();let prior_bytes=serde_json::to_value(&prior).unwrap();start(&e,"en").unwrap();wait(&e);let s=e.snapshot();assert_eq!(s.job.as_ref().unwrap().status,"awaiting_approval");assert_eq!(serde_json::to_value(&s.history[0]).unwrap(),prior_bytes);assert_eq!(s.history[0].workflow_id,crate::general::ID);assert_eq!(s.purpose_job_context.len(),1);assert_eq!(core_api::snapshot(&s)["jobs"][1]["purpose"]["contentLanguage"],Value::Null);
 let mut unknown=prior.clone();unknown.job_id="unclassified-old-job".into();unknown.workflow=crate::general::workflow();unknown.workflow_id=crate::general::ID.into();unknown.status="disconnected".into();let before=serde_json::to_value(&unknown).unwrap();assert_eq!(purposes::view(&unknown,&s)["purposeId"],Value::Null);assert_eq!(purposes::view(&unknown,&s)["contextSource"],"UNCLASSIFIED");assert_eq!(serde_json::to_value(&unknown).unwrap(),before);
 write(&p,"legacy-result.json",&json!({"result":"OFFLINE_PASS","snapshot":core_api::snapshot(&s),"oldJobUnchanged":true,"unclassified":purposes::view(&unknown,&s)}));e.get_rpc().unwrap().shutdown();
}
#[test]fn purpose_job_save_failure_rolls_back_context_and_no_worker(){
 let(p,e)=fixture("job-save-failure");e.data.lock().unwrap().store.0.execute_batch("CREATE TRIGGER fail_job AFTER INSERT ON jobs BEGIN SELECT RAISE(ABORT,'injected job failure'); END;").unwrap();assert!(start(&e,"en").unwrap_err().contains("injected job failure"));assert_eq!(counts(&e),(0,0));assert!(e.snapshot().job.is_none());assert!(!e.worker.load(Ordering::SeqCst));assert!(!p.join("offline-peer.jsonl").exists());e.get_rpc().unwrap().shutdown();
}
#[test]fn purpose_failed_second_start_preserves_prior_completed_job_and_approval_hash(){
 let(p,e)=fixture("prior-job-rollback");start(&e,"ja").unwrap();wait(&e);let s=e.snapshot();let j=s.job.as_ref().unwrap();e.answer_content_review(&j.job_id,&s.approvals[0].id,"accept").unwrap();wait(&e);let before=e.snapshot();assert_eq!(before.job.as_ref().unwrap().status,"completed");let before_json=serde_json::to_value(&before).unwrap();let product=before.job.as_ref().unwrap().artifacts.iter().find(|a|a.name=="post.txt").unwrap();let bytes=fs::read(&product.path).unwrap();
 e.data.lock().unwrap().store.0.execute_batch("CREATE TRIGGER fail_second_context AFTER INSERT ON purpose_job_context BEGIN SELECT RAISE(ABORT,'injected second context failure'); END;").unwrap();assert!(start(&e,"en").is_err());assert_eq!(serde_json::to_value(e.snapshot()).unwrap(),before_json);assert_eq!(serde_json::to_value(e.data.lock().unwrap().store.load().unwrap().unwrap()).unwrap(),before_json);assert_eq!(counts(&e),(1,1));assert_eq!(fs::read(&product.path).unwrap(),bytes);crate::sns::approved(e.snapshot().job.as_ref().unwrap()).unwrap();assert_eq!(fs::read_to_string(p.join("offline-peer.jsonl")).unwrap().lines().count(),2);e.get_rpc().unwrap().shutdown();write(&p,"prior-job-result.json",&json!({"result":"OFFLINE_PASS","priorJob":j.job_id,"priorSnapshotUnchanged":true,"approvalAndProductHashUnchanged":true,"rpcTurns":2,"additionalTurns":0}));
}
#[test]fn purpose_context_is_immutable_and_missing_or_tampered_storage_fails_closed(){
 let(p,e)=fixture("immutable");start(&e,"ja").unwrap();wait(&e);let before=serde_json::to_value(e.snapshot()).unwrap();let id=e.snapshot().job.unwrap().job_id;
 assert!(e.update(|s|{s.purpose_job_context.remove(&id);Ok(())}).is_err());assert!(e.update(|s|{s.purpose_job_context.get_mut(&id).unwrap().content_language="en".into();Ok(())}).is_err());assert!(e.update(|s|{s.purpose_job_context.get_mut(&id).unwrap().workflow_sha256="wrong".into();Ok(())}).is_err());assert_eq!(serde_json::to_value(e.snapshot()).unwrap(),before);assert_eq!(counts(&e),(1,1));
 e.data.lock().unwrap().store.0.execute("DELETE FROM purpose_job_context WHERE job_id=?1",[id]).unwrap();assert!(e.data.lock().unwrap().store.load().is_err());e.get_rpc().unwrap().shutdown();write(&p,"immutability-result.json",&json!({"result":"OFFLINE_PASS","overwriteRejected":true,"deletionRejected":true,"missingDbRowRejectedOnLoad":true}));
}
#[test]fn purpose_boundary_rejects_planned_injected_and_bad_requests_before_execution(){
 let(p,e)=fixture("bad-input");let c=core_api::perform(&e,Action::ListPurposes).unwrap();assert_eq!(c,purposes::catalog());write(&p,"catalog.json",&c);
 for v in [json!({"action":"startPurpose","purposeId":"research","definitionVersion":purposes::VERSION,"input":{}}),json!({"action":"startPurpose","purposeId":"missing","definitionVersion":purposes::VERSION,"input":{}}),json!({"action":"startPurpose","purposeId":"social-text","definitionVersion":"0","input":input("ja")})]{let a=serde_json::from_value(v).unwrap();assert!(core_api::perform(&e,a).is_err());}
 for v in [json!({"action":"startPurpose","purposeId":"social-text","definitionVersion":purposes::VERSION,"input":input("ja"),"workflow":{}}),json!({"action":"startPurpose","purposeId":"social-text","definitionVersion":purposes::VERSION,"input":input("ja"),"executor":"codex"})]{assert!(serde_json::from_value::<Action>(v).is_err());}
 assert_eq!(counts(&e),(0,0));assert!(!p.join("offline-peer.jsonl").exists());e.get_rpc().unwrap().shutdown();
}
#[test]fn purpose_error_after_committed_start_keeps_context_and_is_not_marked_unsent(){
 let(p,e)=fixture("post-commit-failure");let source=p.join("provided.md");fs::write(&source,"provided facts only").unwrap();let mut settings=e.snapshot().settings;settings.input_paths=vec![source.to_string_lossy().into()];e.save_setup(settings).unwrap();*e.rpc.lock().unwrap()=Some(Rpc::phase9_fixture(&p).unwrap());
 e.data.lock().unwrap().store.0.execute_batch("CREATE TRIGGER fail_input_artifact AFTER INSERT ON artifacts BEGIN SELECT RAISE(ABORT,'injected input save failure'); END;").unwrap();let error=start(&e,"ja").unwrap_err();assert!(!error.starts_with("[PURPOSE_NOT_STARTED] "),"unexpected pre-start rejection: {error}");assert_eq!(counts(&e),(1,1));assert_eq!(e.snapshot().job.as_ref().unwrap().status,"failed");assert!(!e.worker.load(Ordering::SeqCst));assert!(!p.join("offline-peer.jsonl").exists());let s=e.snapshot();purposes::validate_context(&s.purpose_job_context[&s.job.as_ref().unwrap().job_id],s.job.as_ref().unwrap()).unwrap();
 write(&p,"post-commit-result.json",&json!({"result":"OFFLINE_PASS","error":error,"snapshot":core_api::snapshot(&s),"jobs":1,"contexts":1,"rpcTurns":0,"markedUnsent":false}));e.get_rpc().unwrap().shutdown();
}
#[test]fn purpose_concurrent_start_allows_one_job_and_unknown_never_restarts(){
 let(p,e)=fixture("concurrent");let a=e.clone();let b=e.clone();let x=std::thread::spawn(move||start(&a,"ja"));let y=std::thread::spawn(move||start(&b,"en"));let results=[x.join().unwrap(),y.join().unwrap()];assert_eq!(results.iter().filter(|v|v.is_ok()).count(),1);wait(&e);assert_eq!(counts(&e),(1,1));let context=e.snapshot().purpose_job_context.clone();e.get_rpc().unwrap().shutdown();drop(e);
 let e=Engine::open(&p,None).unwrap();assert_eq!(e.snapshot().job.as_ref().unwrap().status,"disconnected");assert!(start(&e,"ja").is_err());assert_eq!(e.snapshot().purpose_job_context,context);assert_eq!(counts(&e),(1,1));assert_eq!(fs::read_to_string(p.join("offline-peer.jsonl")).unwrap().lines().count(),2);write(&p,"unknown-result.json",&json!({"result":"OFFLINE_PASS","duplicates":0,"restartStatus":"UNKNOWN/disconnected","resends":0}));
}
